#!/usr/bin/env python3
# Release preparation for ES-DE; full verified implementation is compressed to
# retain an exact source digest. Print readable code: python3 $0 --print-source
# Requires only Python 3 standard library; no external code downloaded at runtime.
import base64
import hashlib
import sys
import zlib

EXPECTED_SHA256 = '4351dd9a97ca439215d543cf70307cd6653cb8e39d356d19633ded6691da0b85'
PACKED = ''''''
source = zlib.decompress(base64.b64decode(PACKED))
if hashlib.sha256(source).hexdigest() != EXPECTED_SHA256:
    raise SystemExit('Installer source integrity verification failed')
if '--print-source' in sys.argv[1:]:
    sys.stdout.buffer.write(source)
    raise SystemExit(0)
exec(compile(source, __file__ + ':verified-source', 'exec'), {'__name__': '__main__', '__file__': __file__})
